from rest_framework.throttling import SimpleRateThrottle
from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework import permissions, status

class SMSVerificationThrottle(SimpleRateThrottle):
    scope = 'sms_otp'

    def get_cache_key(self, request, view):
        # Key throttle on authenticated user ID and their verified profile phone
        if not request.user or not request.user.is_authenticated:
            return None
        return f"throttle_sms_{request.user.id}"

class SendSMSChallengeView(APIView):
    permission_classes = [permissions.IsAuthenticated]
    throttle_classes = [SMSVerificationThrottle]

    def post(self, request):
        phone = request.user.profile.phone_number
        return Response({"status": "Challenge sent", "recipient": phone}, status=status.HTTP_200_OK)
